/* Offline customer retention dashboard. Data is generated by the project pipeline. */
(() => {
  'use strict';
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const data = window.RETENTION_DATA;
  if (!data || !Array.isArray(data.customers)) {
    const error = $('#load-error');
    error.hidden = false;
    error.textContent = 'Dashboard data is not available yet. Run the project pipeline from the project folder to generate dashboard/data.js, then reopen this page.';
    $('#filter-count').textContent = 'Data unavailable';
    return;
  }
  const numeric = value => Number.isFinite(Number(value)) ? Number(value) : 0;
  const money = (value, compact = false) => new Intl.NumberFormat('en-US', { style: 'currency', currency: data.meta?.currency || 'USD', maximumFractionDigits: compact ? 1 : 0, notation: compact ? 'compact' : 'standard' }).format(numeric(value));
  const count = value => new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 }).format(numeric(value));
  const pct = (value, digits = 0) => new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: digits, minimumFractionDigits: digits }).format(numeric(value));
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const sum = (rows, key) => rows.reduce((total, row) => total + numeric(row[key]), 0);
  const average = (rows, key) => rows.length ? sum(rows, key) / rows.length : 0;
  const dateObject = value => new Date(`${String(value).slice(0, 10)}T00:00:00Z`);
  const dateLabel = (value, options = { day: '2-digit', month: 'short', year: 'numeric' }) => { const d = dateObject(value); return Number.isNaN(d.getTime()) ? String(value ?? '—') : new Intl.DateTimeFormat('en-GB', { ...options, timeZone: 'UTC' }).format(d); };
  const monthLabel = value => dateLabel(value, { month: 'short', year: '2-digit' });
  const titleCase = value => String(value ?? '').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  const metric = value => value === null || value === undefined || !Number.isFinite(Number(value)) ? 'N/A' : Number(value).toFixed(3);
  const customers = data.customers;
  const state = { channel: '', country: '', risk: '', segment: '', search: '', sort: 'churn_probability', direction: -1, page: 1, pageSize: 12, period: 12, cohortRange: 'recent', view: 'overview' };
  const colors = { High: '#eb5b60', Medium: '#d8a33d', Low: '#00b386' };
  const views = {
    overview: ['OVERVIEW', 'Know who stays. Understand who may leave.', 'Turn customer behavior into a more focused retention strategy.'],
    customers: ['CUSTOMER SIGNALS', 'Every customer has a story.', 'Find the behavioral signals that deserve a closer look.'],
    retention: ['COHORT RETENTION', 'Loyalty, over the long run.', 'Follow each signup cohort from its first month onward.'],
    methods: ['MODEL & METHODS', 'Confidence starts with transparency.', 'Inspect the evaluation, assumptions, and limits behind each prediction.']
  };

  function populateFilter(selector, values) {
    const select = $(selector);
    [...new Set(values.filter(value => value !== null && value !== undefined && value !== ''))].sort().forEach(value => {
      const option = document.createElement('option'); option.value = String(value); option.textContent = String(value); select.append(option);
    });
  }
  populateFilter('#channel-filter', customers.map(c => c.acquisition_channel));
  populateFilter('#country-filter', customers.map(c => c.country));
  populateFilter('#segment-filter', customers.map(c => c.segment));
  $('#score-date').textContent = dateLabel(data.meta?.score_date || '2026-10-01');
  $('#method-score-date').textContent = dateLabel(data.meta?.score_date || '2026-10-01');
  const isSynthetic = data.meta?.synthetic === true;
  $('#footer-data').textContent = `${isSynthetic ? 'Synthetic data' : 'Imported data'} · ${count(data.meta?.customer_count || customers.length)} signups · ${count(data.meta?.order_count || 0)} orders · ${data.meta?.currency || 'USD'}`;
  $('.sidebar-footer small').textContent = `Retention analytics · ${data.meta?.currency || 'USD'}`;
  $('.demo-badge').textContent = isSynthetic ? 'DEMO' : 'IMPORTED';
  if (!isSynthetic) {
    $('.sidebar-note strong').textContent = 'Imported customer data';
    $('.sidebar-note p').textContent = 'Customer lifecycle analysis using the supplied purchase history.';
    $('.method-banner p:last-child').textContent = 'These results describe the supplied historical portfolio. Future performance can change as customer behavior and acquisition mix change.';
  }

  function scopedCustomers() {
    return customers.filter(c => (!state.channel || c.acquisition_channel === state.channel) && (!state.country || c.country === state.country) && (!state.risk || c.risk_band === state.risk));
  }
  function tableCustomers() {
    const rows = scopedCustomers().filter(c => (!state.segment || c.segment === state.segment) && (!state.search || String(c.customer_id).toLowerCase().includes(state.search.toLowerCase())));
    return rows.sort((a, b) => {
      const av = a[state.sort], bv = b[state.sort];
      if (state.sort === 'customer_id') return String(av).localeCompare(String(bv), undefined, { numeric: true }) * state.direction;
      const difference = (numeric(av) - numeric(bv)) * state.direction;
      return difference || String(a.customer_id).localeCompare(String(b.customer_id), undefined, { numeric: true });
    });
  }
  function card(title, value, description, { featured = false, icon = '↗' } = {}) {
    return `<article class="kpi-card${featured ? ' featured' : ''}"><div class="kpi-title"><span>${title}</span><span class="kpi-icon" aria-hidden="true">${icon}</span></div><p class="kpi-value">${value}</p><p class="kpi-footnote">${description}</p></article>`;
  }
  function riskBadge(risk) {
    const normalized = ['High', 'Medium', 'Low'].includes(risk) ? risk : 'Low';
    return `<span class="risk-badge ${normalized.toLowerCase()}"><i aria-hidden="true"></i>${esc(normalized)} risk</span>`;
  }
  function renderOverview(rows) {
    const high = rows.filter(c => c.risk_band === 'High');
    const exposure = sum(rows, 'revenue_at_risk');
    $('#overview-kpis').innerHTML = [
      card('Eligible customers', count(rows.length), `<span class="accent">${pct(customers.length ? rows.length / customers.length : 0)}</span> of scored portfolio`, { icon: '◉' }),
      card('Average churn probability', pct(average(rows, 'churn_probability'), 1), 'No purchase in the next 90 days', { icon: '↗' }),
      card('90-day revenue exposure', money(exposure, true), 'Historical pace × churn probability', { featured: true, icon: '$' }),
      card('High-risk customers', count(high.length), `<span class="orange">${pct(rows.length ? high.length / rows.length : 0, 1)}</span> of selected customers`, { icon: '◷' })
    ].join('');
    $('#filter-count').textContent = `${count(rows.length)} of ${count(customers.length)} eligible customers`;
    $('#nav-risk-count').textContent = count(high.length);
    renderRisk(rows);
    const priorities = [...rows].sort((a, b) => numeric(b.revenue_at_risk) - numeric(a.revenue_at_risk)).slice(0, 5);
    $('#priority-list').innerHTML = priorities.length ? priorities.map(c => `<div class="priority-row" data-customer="${esc(c.customer_id)}" role="button" tabindex="0" aria-label="Open customer ${esc(c.customer_id)} details"><span class="customer-avatar" aria-hidden="true">${esc(String(c.customer_id).slice(-2))}</span><div><div class="priority-id">${esc(c.customer_id)}</div><div class="priority-segment">${esc(c.segment)}</div></div>${riskBadge(c.risk_band)}<span class="priority-amount">${money(c.revenue_at_risk)}</span><span class="priority-arrow" aria-hidden="true">↗</span></div>`).join('') : '<p class="empty-state">No eligible customers match these filters.</p>';
    $('#high-risk-summary').textContent = count(high.length);
    $('#high-risk-exposure').textContent = money(sum(high, 'revenue_at_risk'));
    renderScenario(rows);
  }
  function renderRisk(rows) {
    const parts = ['High', 'Medium', 'Low'].map(name => ({ name, value: rows.filter(c => c.risk_band === name).length }));
    const circumference = 2 * Math.PI * 60;
    let offset = 0;
    const arcs = parts.map(part => {
      const length = rows.length ? part.value / rows.length * circumference : 0;
      const arc = length ? `<circle cx="92" cy="80" r="60" fill="none" stroke="${colors[part.name]}" stroke-width="15" stroke-dasharray="${Math.max(0, length - 3)} ${circumference - Math.max(0, length - 3)}" stroke-dashoffset="${-offset}" transform="rotate(-90 92 80)"/>` : '';
      offset += length; return arc;
    }).join('');
    $('#risk-chart').innerHTML = `<div class="risk-donut-wrap"><svg viewBox="0 0 184 164" role="img" aria-label="Customer risk distribution: ${parts.map(p => `${p.name}, ${p.value}`).join('; ')}"><circle cx="92" cy="80" r="60" fill="none" stroke="#f0f2f6" stroke-width="15"/>${arcs}</svg><div class="donut-center"><strong>${pct(average(rows, 'churn_probability'), 1)}</strong><span>average churn risk</span></div></div><div class="risk-rows">${parts.map(p => `<div class="risk-row"><i style="background:${colors[p.name]}" aria-hidden="true"></i><span>${p.name} risk</span><strong>${count(p.value)}</strong><small>${pct(rows.length ? p.value / rows.length : 0)}</small></div>`).join('')}</div>`;
  }
  function renderScenario(rows = scopedCustomers()) {
    const recovery = numeric($('#recovery-slider').value) / 100;
    $('#scenario-value').textContent = money(sum(rows, 'revenue_at_risk') * recovery);
    $('#recovery-label').textContent = pct(recovery);
    $('#recovery-slider').style.background = `linear-gradient(to right,#00b386 ${recovery * 200}%,#e7edf0 ${recovery * 200}%)`;
    $('#recovery-slider').setAttribute('aria-valuetext', `${pct(recovery)} assumed recovery, ${money(sum(rows, 'revenue_at_risk') * recovery)} illustrative retained exposure`);
  }
  function renderSales() {
    let actual = [...(data.monthly_sales || [])].sort((a, b) => a.month.localeCompare(b.month));
    if (!actual.length) actual = (data.forecast || []).filter(r => r.series === 'Actual').sort((a, b) => a.month.localeCompare(b.month));
    if (state.period) actual = actual.slice(-state.period);
    const forecast = (data.forecast || []).filter(r => r.series === 'Forecast' || (r.forecast !== null && r.forecast !== undefined && r.forecast !== '' && r.series !== 'Actual')).sort((a, b) => a.month.localeCompare(b.month));
    $('#forecast-total').textContent = money(sum(forecast, 'forecast'), true);
    const nominalCoverage = numeric(data.forecast_metrics?.intervals?.nominal_coverage);
    $('#forecast-note').textContent = `Global sales are unaffected by customer filters. ${nominalCoverage ? `${pct(nominalCoverage)} nominal intervals are approximate; ` : 'Intervals are approximate; '}future outcomes can fall outside the band.`;
    const container = $('#sales-chart');
    if (!actual.length && !forecast.length) { container.innerHTML = '<p class="empty-state">No monthly sales data available.</p>'; return; }
    const combined = [...actual.map(r => ({ ...r, value: numeric(r.revenue), type: 'Actual' })), ...forecast.map(r => ({ ...r, value: numeric(r.forecast), type: 'Forecast' }))];
    const w = 760, h = 258, margin = { top: 20, right: 27, bottom: 39, left: 61 };
    const plotW = w - margin.left - margin.right, plotH = h - margin.top - margin.bottom;
    const rawMax = Math.max(1, ...combined.map(r => Math.max(r.value, numeric(r.upper))));
    const magnitude = Math.pow(10, Math.floor(Math.log10(rawMax)));
    const maxY = Math.ceil(rawMax * 1.1 / (magnitude / 2)) * (magnitude / 2);
    const x = index => margin.left + index / Math.max(1, combined.length - 1) * plotW;
    const y = value => margin.top + plotH * (1 - Math.max(0, numeric(value)) / maxY);
    const line = list => list.map((p, i) => `${i ? 'L' : 'M'}${x(p.index).toFixed(2)},${y(p.value).toFixed(2)}`).join(' ');
    const actualPoints = actual.map((r, index) => ({ index, value: numeric(r.revenue) }));
    const forecastPoints = forecast.map((r, index) => ({ index: actual.length + index, value: numeric(r.forecast) }));
    const bridge = actualPoints.length ? [actualPoints[actualPoints.length - 1], ...forecastPoints] : forecastPoints;
    const area = actualPoints.length ? `${line(actualPoints)} L${x(actualPoints[actualPoints.length - 1].index)},${y(0)} L${x(actualPoints[0].index)},${y(0)} Z` : '';
    const upperPoints = forecast.map((r, index) => ({ index: actual.length + index, value: numeric(r.upper) || numeric(r.forecast) }));
    const lowerPoints = forecast.map((r, index) => ({ index: actual.length + index, value: numeric(r.lower) })).reverse();
    const band = upperPoints.length ? `${line(upperPoints)} ${lowerPoints.map(p => `L${x(p.index)},${y(p.value)}`).join(' ')} Z` : '';
    const grid = Array.from({ length: 5 }, (_, i) => { const v = maxY * i / 4; return `<line x1="${margin.left}" y1="${y(v)}" x2="${w - margin.right}" y2="${y(v)}" stroke="#edf0f5" stroke-dasharray="3 4"/><text x="${margin.left - 12}" y="${y(v) + 3}" text-anchor="end" fill="#8b93a6" font-size="9">${esc(money(v, true))}</text>`; }).join('');
    const ticks = [...new Set(Array.from({ length: Math.min(7, combined.length) }, (_, i) => Math.round(i * (combined.length - 1) / Math.max(1, Math.min(7, combined.length) - 1))))];
    const tickLabels = ticks.map(i => `<text x="${x(i)}" y="${h - 14}" text-anchor="middle" fill="#8b93a6" font-size="9">${esc(monthLabel(combined[i].month))}</text>`).join('');
    const forecastStart = actual.length && forecast.length ? (x(actual.length - 1) + x(actual.length)) / 2 : x(0);
    const boundary = forecast.length ? `<rect x="${forecastStart}" y="${margin.top}" width="${w - margin.right - forecastStart}" height="${plotH}" fill="#fafaff"/><line x1="${forecastStart}" y1="${margin.top}" x2="${forecastStart}" y2="${y(0)}" stroke="#dcdff0" stroke-dasharray="3 5"/><text x="${forecastStart + 9}" y="${margin.top + 10}" font-size="8" fill="#8d94bb" letter-spacing="1">FORECAST</text>` : '';
    const hitTargets = combined.map((r, i) => `<circle cx="${x(i)}" cy="${y(r.value)}" r="7" fill="transparent" tabindex="0" data-chart-index="${i}" aria-label="${esc(`${monthLabel(r.month)} ${r.type}: ${money(r.value)}${r.type === 'Forecast' ? `; approximate interval ${money(r.lower)} to ${money(r.upper)}` : ''}`)}"><title>${esc(`${monthLabel(r.month)} · ${r.type} · ${money(r.value)}`)}</title></circle>`).join('');
    container.innerHTML = `<svg viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="sales-title sales-description"><title id="sales-title">Monthly sales and six-month revenue forecast</title><desc id="sales-description">Actual sales are solid green; forecasts are dashed indigo with an approximate prediction interval. Focus any month for its value.</desc><defs><linearGradient id="actual-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#8ce5c5" stop-opacity=".5"/><stop offset="100%" stop-color="#e8faf3" stop-opacity=".1"/></linearGradient></defs>${boundary}${grid}${band ? `<path d="${band}" fill="#dbe0ff" opacity=".58"/>` : ''}${area ? `<path d="${area}" fill="url(#actual-fill)"/>` : ''}${actualPoints.length ? `<path d="${line(actualPoints)}" fill="none" stroke="#00b386" stroke-width="2.7" stroke-linejoin="round" stroke-linecap="round"/>` : ''}${bridge.length ? `<path d="${line(bridge)}" fill="none" stroke="#5367ff" stroke-width="2.2" stroke-dasharray="5 5" stroke-linejoin="round" stroke-linecap="round"/>` : ''}${actualPoints.length ? `<circle cx="${x(actualPoints[actualPoints.length - 1].index)}" cy="${y(actualPoints[actualPoints.length - 1].value)}" r="3.5" fill="#00b386" stroke="#fff" stroke-width="2"/>` : ''}${tickLabels}${hitTargets}</svg><div class="chart-tooltip" role="status" hidden></div>`;
    const tooltip = $('.chart-tooltip', container);
    $$('[data-chart-index]', container).forEach(point => {
      const show = () => { const i = Number(point.dataset.chartIndex), r = combined[i]; tooltip.innerHTML = `${esc(monthLabel(r.month))} · ${r.type}<strong>${money(r.value)}</strong>${r.type === 'Forecast' ? `<small>Interval ${money(r.lower)} – ${money(r.upper)}</small>` : ''}`; tooltip.style.left = `${Math.max(15, Math.min(85, x(i) / w * 100))}%`; tooltip.style.top = `${y(r.value) / h * 100}%`; tooltip.hidden = false; };
      point.addEventListener('mouseenter', show); point.addEventListener('focus', show); point.addEventListener('mouseleave', () => { tooltip.hidden = true; }); point.addEventListener('blur', () => { tooltip.hidden = true; });
    });
  }
  function renderSegments(rows) {
    const segments = [...new Set(rows.map(c => c.segment))].map(name => { const group = rows.filter(c => c.segment === name); return { name, count: group.length, risk: average(group, 'churn_probability') }; }).sort((a, b) => b.count - a.count);
    const maxCount = Math.max(1, ...segments.map(s => s.count));
    $('#segment-chart').innerHTML = segments.length ? `<div class="segment-rows">${segments.map(s => `<div class="segment-row"><strong>${esc(s.name)}</strong><div class="segment-bar-bg" role="img" aria-label="${esc(s.name)}: ${count(s.count)} customers, ${pct(s.risk)} average risk"><div class="segment-bar" style="width:${s.count / maxCount * 100}%"></div></div><span>${count(s.count)}</span><span>${pct(s.risk)} risk</span></div>`).join('')}</div>` : '<p class="empty-state">No segments match these filters.</p>';
  }
  function renderTable() {
    const rows = tableCustomers();
    const pages = Math.max(1, Math.ceil(rows.length / state.pageSize));
    state.page = Math.min(state.page, pages);
    const start = (state.page - 1) * state.pageSize, current = rows.slice(start, start + state.pageSize);
    $('#table-match-count').textContent = `${count(rows.length)} matches`;
    $('#customer-tbody').innerHTML = current.length ? current.map(c => `<tr><td><button class="customer-link" data-customer="${esc(c.customer_id)}" aria-label="View customer ${esc(c.customer_id)}">${esc(c.customer_id)}</button></td><td>${esc(c.segment)}</td><td><div class="risk-cell"><span class="risk-probability">${pct(c.churn_probability)}</span>${riskBadge(c.risk_band)}</div></td><td>${count(c.recency_days)} days ago</td><td class="numeric">${money(c.revenue_at_risk)}</td><td class="action-cell">${esc(c.recommended_action)}</td></tr>`).join('') : '<tr><td colspan="6"><p class="empty-state">No customers match these filters. Try another ID or reset the portfolio filters.</p></td></tr>';
    $('#table-range').textContent = rows.length ? `Showing ${count(start + 1)}–${count(Math.min(start + state.pageSize, rows.length))} of ${count(rows.length)} customers` : 'No matching customers';
    $('#page-number').textContent = `${state.page} / ${pages}`;
    $('#previous-page').disabled = state.page <= 1;
    $('#next-page').disabled = state.page >= pages;
    $('#export-customers').disabled = !rows.length;
    $$('.sort-button').forEach(button => { const selected = button.dataset.sort === state.sort; button.closest('th').setAttribute('aria-sort', selected ? (state.direction === 1 ? 'ascending' : 'descending') : 'none'); $('span', button).textContent = selected ? (state.direction === 1 ? '↑' : '↓') : '↕'; });
  }
  function renderCohorts() {
    const cohorts = data.cohorts || [];
    const weightedRetention = index => { const observed = cohorts.filter(c => numeric(c.month_index) === index); const denominator = sum(observed, 'cohort_size'); return { value: denominator ? sum(observed, 'retained_customers') / denominator : null, cohorts: observed.length }; };
    $('#cohort-kpis').innerHTML = [1, 3, 6].map((m, i) => { const r = weightedRetention(m); return card(`Month ${m} purchase retention`, r.value === null ? 'N/A' : pct(r.value, 1), `${r.cohorts} observed cohorts · weighted by size`, { featured: i === 0, icon: '↻' }); }).join('');
    let groups = [...new Set(cohorts.map(c => c.cohort_month))].sort();
    if (state.cohortRange === 'recent') groups = groups.slice(-18);
    if (state.cohortRange === 'early') groups = groups.slice(0, 18);
    const index = new Map(cohorts.map(c => [`${c.cohort_month}:${numeric(c.month_index)}`, c]));
    const cells = groups.map(group => {
      const any = cohorts.find(c => c.cohort_month === group);
      const row = Array.from({ length: 13 }, (_, month) => {
        const record = index.get(`${group}:${month}`);
        if (!record) return '<td class="unobserved" aria-label="Not observed" title="Not observed"></td>';
        const rate = Math.max(0, Math.min(1, numeric(record.retention_rate)));
        const lightness = 97 - rate * 70, saturation = 55 + rate * 15;
        return `<td style="background:hsl(158 ${saturation}% ${lightness}%);color:${rate > .94 ? '#fff' : '#082219'}" title="${esc(`${monthLabel(group)}, month ${month}: ${count(record.retained_customers)} of ${count(record.cohort_size)} customers (${pct(rate, 1)})`)}">${pct(rate)}</td>`;
      }).join('');
      return `<tr><th scope="row">${esc(monthLabel(group))}</th><td class="cohort-size">${count(any?.cohort_size)}</td>${row}</tr>`;
    }).join('');
    $('#cohort-heatmap').innerHTML = groups.length ? `<table class="cohort-table"><caption class="sr-only">Calendar month purchase retention of signup cohorts. M0 is the signup calendar month; empty cells are unobserved.</caption><thead><tr><th scope="col">Signup cohort</th><th scope="col">Customers</th>${Array.from({ length: 13 }, (_, i) => `<th scope="col">M${i}</th>`).join('')}</tr></thead><tbody>${cells}</tbody></table>` : '<p class="empty-state">No cohort data available.</p>';
  }
  function renderMethods() {
    const metrics = data.metrics || {}, test = metrics.test || {};
    $('#model-kpis').innerHTML = [
      card('Test ROC-AUC', metric(test.roc_auc), 'Discrimination across risk thresholds', { featured: true, icon: '↗' }),
      card('Test average precision', metric(test.average_precision), 'Precision–recall ranking quality', { icon: '◎' }),
      card('Test recall', test.recall == null ? 'N/A' : pct(test.recall, 1), 'At the validation-selected threshold', { icon: '↻' }),
      card('Top-decile lift', metrics.top_decile_lift == null ? 'N/A' : `${numeric(metrics.top_decile_lift).toFixed(2)}×`, 'Churn rate vs. the test population', { icon: '↗' })
    ].join('');
    const importance = [...(data.feature_importance || [])].sort((a, b) => numeric(b.importance) - numeric(a.importance)).slice(0, 10);
    const largest = Math.max(.000001, ...importance.map(r => Math.abs(numeric(r.importance))));
    const friendly = { recency_days: 'Days since last purchase', order_trend: 'Recent order trend', orders_30d: 'Orders · last 30 days', orders_90d: 'Orders · last 90 days', orders_180d: 'Orders · last 180 days', revenue_90d: 'Revenue · last 90 days', revenue_180d: 'Revenue · last 180 days', avg_order_value: 'Average order value', avg_gap_days: 'Average purchase gap', gap_std_days: 'Purchase gap variability', tenure_days: 'Customer tenure', lifetime_orders: 'Lifetime orders', lifetime_revenue: 'Lifetime revenue', days_to_first_order: 'Days to first order', acquisition_channel: 'Acquisition channel', country: 'Country' };
    $('#importance-chart').innerHTML = importance.length ? `<div class="importance-rows">${importance.map(r => `<div class="importance-row"><span class="importance-name">${esc(friendly[r.feature] || titleCase(r.feature))}</span><div class="importance-track" role="img" aria-label="${esc(r.feature)} importance ${numeric(r.importance).toFixed(4)}"><div class="importance-bar" style="width:${Math.abs(numeric(r.importance)) / largest * 100}%;${numeric(r.importance) < 0 ? 'background:#d8a33d;' : ''}"></div></div><span class="importance-value">${numeric(r.importance).toFixed(3)}</span></div>`).join('')}</div>` : '<p class="empty-state">Feature importance is not available.</p>';
    const high = metrics.risk_thresholds?.high, medium = metrics.risk_thresholds?.medium;
    if (high !== undefined && medium !== undefined) $('#risk-definition').textContent = `High: probability ≥ ${pct(high, 1)}. Medium: ${pct(medium, 1)} to below ${pct(high, 1)}. Low: below ${pct(medium, 1)}. The High threshold maximizes validation F2; Medium is half that threshold.`;
    const selected = data.forecast_metrics?.selected_model;
    const wape = data.forecast_metrics?.selected?.wape;
    $('#forecast-definition').textContent = `Six monthly periods ahead${selected ? ` using ${titleCase(selected).toLowerCase()}` : ''}, selected with rolling-origin evaluation.${wape !== undefined && wape !== null ? ` Historical backtest WAPE: ${pct(wape, 1)}.` : ''} Intervals are approximate and based on historical errors.`;
    if (metrics.selected_model) $('#importance-note').textContent = `Selected model: ${titleCase(metrics.selected_model).toLowerCase()}. Importance measures predictive contribution, not causality. Customer action reasons use transparent behavioral rules.`;
  }
  function renderCustomerViews() {
    const rows = scopedCustomers(); renderOverview(rows); renderSegments(rows); renderTable();
  }
  function showView(name, updateUrl = true) {
    const view = views[name] ? name : 'overview';
    state.view = view;
    $$('.view').forEach(section => { section.hidden = section.id !== `view-${view}`; });
    $$('.nav-item').forEach(button => { const current = button.dataset.view === view; button.classList.toggle('active', current); if (current) button.setAttribute('aria-current', 'page'); else button.removeAttribute('aria-current'); });
    $('#view-crumb').textContent = views[view][0]; $('#view-title').textContent = views[view][1]; $('#view-description').textContent = views[view][2];
    document.title = `${titleCase(view === 'methods' ? 'model & methods' : view === 'customers' ? 'customer signals' : view === 'retention' ? 'cohort retention' : view)} · Continuum`;
    if (updateUrl) window.scrollTo({top:0,behavior:'auto'});
    if (updateUrl) { try { history.replaceState(null, '', `#${view}`); } catch (_) { /* Navigation still works if local browser history is restricted. */ } }
  }
  function openCustomer(id) {
    const c = customers.find(customer => String(customer.customer_id) === String(id));
    if (!c) return;
    $('#customer-detail').innerHTML = `<h2 id="dialog-title">${esc(c.customer_id)}</h2><p class="dialog-subtitle">${esc(c.segment)} · ${esc(c.country)} · ${esc(c.acquisition_channel)}</p><div class="detail-risk"><div><strong>${pct(c.churn_probability, 1)}</strong><p>probability of no purchase in the next 90 days</p></div>${riskBadge(c.risk_band)}</div><div class="detail-metrics"><div><strong>${count(c.recency_days)} days</strong><span>since last completed order</span></div><div><strong>${count(c.orders_90d)}</strong><span>orders in the prior 90 days</span></div><div><strong>${money(c.revenue_at_risk)}</strong><span>modeled 90-day exposure</span></div></div><div class="detail-reason"><h3>Behavioral signal</h3><p>${esc(c.reason)}</p></div><div class="detail-action"><h3>Suggested retention action</h3><p>${esc(c.recommended_action)}</p></div><div class="detail-meta">Signed up ${esc(dateLabel(c.signup_date))} · ${count(c.tenure_days)} days tenure<br>Prior 180-day revenue: ${money(c.revenue_180d)} · 90-day revenue pace: ${money(c.expected_90d_revenue)}<br>Exposure is historical revenue pace × estimated churn probability. Suggested actions have not been experimentally validated.</div>`;
    $('#customer-dialog').showModal();
  }
  let toastTimeout;
  function toast(message) { $('#toast').textContent = message; $('#toast').hidden = false; clearTimeout(toastTimeout); toastTimeout = setTimeout(() => { $('#toast').hidden = true; }, 4500); }
  function exportCustomers() {
    const rows = tableCustomers();
    const fields = ['customer_id', 'country', 'acquisition_channel', 'segment', 'churn_probability', 'risk_band', 'recency_days', 'orders_90d', 'revenue_180d', 'expected_90d_revenue', 'revenue_at_risk', 'reason', 'recommended_action'];
    const csvCell = value => { let s = String(value ?? ''); if (typeof value === 'string' && /^[=+@\-\t\r]/.test(s)) s = `'${s}`; return `"${s.replace(/"/g, '""')}"`; };
    const csv = [fields.join(','), ...rows.map(row => fields.map(field => csvCell(row[field])).join(','))].join('\r\n');
    const url = URL.createObjectURL(new Blob(['\ufeff', csv], { type: 'text/csv;charset=utf-8;' }));
    const anchor = document.createElement('a'); anchor.href = url; anchor.download = `retention-customers-${data.meta?.score_date || 'snapshot'}.csv`; document.body.append(anchor); anchor.click(); anchor.remove(); setTimeout(() => URL.revokeObjectURL(url), 10000);
    toast(`Exported ${count(rows.length)} matching customers.`);
  }
  [['#channel-filter', 'channel'], ['#country-filter', 'country'], ['#risk-filter', 'risk']].forEach(([selector, field]) => $(selector).addEventListener('change', event => { state[field] = event.target.value; state.page = 1; renderCustomerViews(); }));
  $('#reset-filters').addEventListener('click', () => { state.channel = ''; state.country = ''; state.risk = ''; state.segment = ''; state.search = ''; state.page = 1; ['#channel-filter', '#country-filter', '#risk-filter', '#segment-filter', '#customer-search'].forEach(selector => { $(selector).value = ''; }); renderCustomerViews(); });
  $('#customer-search').addEventListener('input', event => { state.search = event.target.value.trim(); state.page = 1; renderTable(); });
  $('#segment-filter').addEventListener('change', event => { state.segment = event.target.value; state.page = 1; renderTable(); });
  $('#recovery-slider').addEventListener('input', () => renderScenario());
  $('#cohort-range').addEventListener('change', event => { state.cohortRange = event.target.value; renderCohorts(); });
  $$('.sort-button').forEach(button => button.addEventListener('click', () => { if (state.sort === button.dataset.sort) state.direction *= -1; else { state.sort = button.dataset.sort; state.direction = state.sort === 'customer_id' ? 1 : -1; } state.page = 1; renderTable(); }));
  $$('.nav-item').forEach(button => button.addEventListener('click', () => showView(button.dataset.view)));
  $$('[data-navigate]').forEach(button => button.addEventListener('click', () => { showView(button.dataset.navigate); window.scrollTo({ top: 0, behavior: 'auto' }); }));
  $$('.period-control button').forEach(button => button.addEventListener('click', () => { state.period = numeric(button.dataset.period); $$('.period-control button').forEach(item => { item.classList.toggle('active', item === button); item.setAttribute('aria-pressed', String(item === button)); }); renderSales(); }));
  $('#previous-page').addEventListener('click', () => { state.page--; renderTable(); });
  $('#next-page').addEventListener('click', () => { state.page++; renderTable(); });
  $('#export-customers').addEventListener('click', exportCustomers);
  $('#close-dialog').addEventListener('click', () => $('#customer-dialog').close());
  $('#customer-dialog').addEventListener('click', event => { if (event.target === $('#customer-dialog')) { const bounds = event.target.getBoundingClientRect(); if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) event.target.close(); } });
  document.addEventListener('click', event => { const trigger = event.target.closest('[data-customer]'); if (trigger) openCustomer(trigger.dataset.customer); });
  document.addEventListener('keydown', event => { const trigger = event.target.closest('.priority-row[data-customer]'); if (trigger && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); openCustomer(trigger.dataset.customer); } });
  window.addEventListener('hashchange', () => showView(location.hash.slice(1), false));
  renderCustomerViews(); renderSales(); renderCohorts(); renderMethods(); showView(location.hash.slice(1), false);
})();
